"""Listening-page layout only; no decoders, simulation or production policy."""
import html


def document(utterances, samples, payloads, bank):
    """Render source-bound normalized sample metadata and embedded FLAC payloads."""
    esc = lambda value: html.escape(str(value), quote=True)
    rooms = {str(s['room_id']): s['room_label'] for s in samples if not s['is_clean']}
    modes = sorted({s['mode_label'] for s in samples if not s['is_clean']})
    cards = []
    for number, utterance in enumerate(utterances, 1):
        tracks = []
        for sample in (s for s in samples if s['utterance_id'] == utterance['id']):
            clean = sample['is_clean']
            label = 'Clean reference' if clean else sample['room_label'] + ' · ' + sample['position_label']
            if clean:
                detail = f"Original clip · {sample['input_duration_s']:.2f} s"
                attributes = 'data-clean="true"'
                ending = ''
            else:
                estimate = sample['estimated_T60_s']
                decay = 'Estimated decay (T60): ' + (f'{estimate:.2f} s from {sample["decay_fit_basis"]}' if estimate is not None else 'unavailable')
                detail = f"{decay} · {sample['mode_label']} · +{sample['tail_duration_s']:.2f} s full response tail"
                attributes = f'data-clean="false" data-room="{esc(sample["room_id"])}" data-position="{esc(sample["position"])}" data-strength="{esc(sample["strength"])}" data-mode="{esc(sample["mode_label"])}"'
                ending = f'<button class="ending" data-start="{max(0, sample["input_duration_s"] - 1.5):.5f}">Hear ending + tail</button>'
            tracks.append(f'<div class="track" {attributes}><div class="track-label"><b>{esc(label)}</b><small>{esc(detail)}</small></div><div class="player"><audio controls preload="none" aria-label="Utterance {number}: {esc(label)}"><source src="data:audio/flac;base64,{payloads[sample["id"]]}" type="audio/flac"></audio>{ending}</div></div>')
        cards.append(f'<section class="utterance" data-voice="{esc(utterance["id"])}"><div class="eyebrow">TRAIN UTTERANCE {number} · {utterance["duration_s"]:.2f} s input</div><h2>{esc(utterance["display_voice_label"])}</h2><p class="transcript" lang="tr">{esc(utterance["original_supplied_transcript"])}</p><details><summary>Source and level matching</summary><p>The supplied TRAIN transcript is unchanged. All input samples are retained. Reverb is loudness matched by RMS over the original clip-duration portion; then every condition for this utterance shares one final headroom gain. The full response tail is audible after the input ends. Speaker identity is not independently verified.</p><code>{esc(utterance["source_id"])}</code></details><div class="tracks">'+''.join(tracks)+'</div></section>')
    room_options = ''.join(f'<option value="{esc(key)}">{esc(value)}</option>' for key, value in rooms.items())
    mode_control = ''
    if len(modes) > 1:
        mode_control = '<label>Simulation<select id="mode"><option value="all">All methods</option>'+''.join(f'<option value="{esc(value)}">{esc(value)}</option>' for value in modes)+'</select></label>'
    else:
        mode_control = '<input id="mode" type="hidden" value="all">'
    total = len(samples)
    alignment = esc(bank['alignment_description'])
    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>More room reverberation · Turkish listening</title><style>
:root{font:16px/1.55 system-ui,-apple-system,Segoe UI,sans-serif;color:#192c40;background:#edf2f5;--muted:#5c6e80;--line:#d9e3ec}*{box-sizing:border-box}body{margin:0}header{background:#152c43;color:white;padding:42px max(5vw,20px) 32px}header .wrap,main{max-width:1220px;margin:auto}.eyebrow{font-size:.73rem;font-weight:750;letter-spacing:.12em;color:#09858d}header .eyebrow{color:#7bdbce}h1{font-size:clamp(2rem,4.5vw,3.4rem);line-height:1.1;letter-spacing:-.04em;margin:12px 0 18px}header p{max-width:840px;color:#cbdae5}.chips{display:flex;gap:8px;flex-wrap:wrap}.chip{border:1px solid #4b647b;background:#29445b;border-radius:20px;padding:6px 12px;font-size:.8rem}main{padding:24px 20px 52px}.controls{position:sticky;top:0;z-index:2;display:flex;flex-wrap:wrap;gap:12px;align-items:end;background:#fff;border:1px solid var(--line);border-radius:12px;padding:16px;box-shadow:0 4px 18px #192c400b}label{font-size:.75rem;font-weight:700;color:var(--muted)}select,button{display:block;font:inherit;font-size:.85rem;padding:8px 10px;border:1px solid #cbd8e3;border-radius:6px;background:white;color:#203b52}select{max-width:230px}button{cursor:pointer}button:hover{background:#e9f6f4}.check{display:flex;align-items:center;padding-bottom:9px;gap:6px}.check input{accent-color:#09858d}.count{font-size:.8rem;color:var(--muted);margin-left:auto;padding-bottom:9px}.note{font-size:.92rem;background:#def1ee;border-left:3px solid #078a87;border-radius:4px;padding:14px 18px;margin:20px 0}.utterance{background:white;border:1px solid var(--line);border-radius:14px;padding:25px;margin:20px 0}h2{font-size:1.2rem;margin:6px 0 14px}.transcript{font-size:1.1rem;line-height:1.75;background:#f2f6f9;border-radius:8px;padding:16px 19px}details{font-size:.82rem;color:var(--muted);margin:12px 0 18px}summary{cursor:pointer}code{font-size:.73rem;overflow-wrap:anywhere}.track{display:grid;grid-template-columns:minmax(250px,1fr) 1.3fr;align-items:center;gap:18px;border-top:1px solid #e1e9ef;padding:14px 0}.track-label b{font-size:.93rem}.track-label small{display:block;color:var(--muted);font-size:.76rem;margin-top:4px}audio{width:100%;height:38px}.player{display:flex;gap:8px;align-items:center}.ending{font-size:.72rem;white-space:nowrap;max-width:110px;padding:7px;line-height:1.3}.provenance{background:white;border:1px solid var(--line);padding:20px 25px;border-radius:12px;font-size:.87rem}.provenance a{color:#087e8b}.foot{font-size:.8rem;color:var(--muted)}[hidden]{display:none!important}@media(max-width:760px){.controls{position:static}.track{grid-template-columns:1fr;gap:8px}.utterance{padding:18px}.player{display:block}.ending{margin-top:5px;max-width:none}.count{margin-left:0}select{max-width:100%}}
</style><header><div class="wrap"><div class="eyebrow">SIMULATED ROOM BANK · LISTENING PREVIEW V3</div><h1>More rooms.<br>Hear the full decay.</h1><p>The same three Turkish TRAIN utterances, from short room responses to much longer reverberation. Compare the clean speech, near and far positions, and the tail after the speech ends.</p><div class="chips"><span class="chip">'''+str(len(rooms))+''' distinct simulated rooms</span><span class="chip">'''+str(total)+''' playable examples</span><span class="chip">Full post-speech tails</span><span class="chip">Production disabled</span></div></div></header><main><div class="controls"><label>Utterance<select id="voice"><option value="all">All three</option><option value="tr_1">Utterance 1</option><option value="tr_2">Utterance 2</option><option value="tr_3">Utterance 3</option></select></label><label>Room<select id="room"><option value="all">All rooms</option>'''+room_options+'''</select></label><label>Decay strength<select id="strength"><option value="all">All estimated ranges</option><option value="short">T60 ≤ 0.4 s</option><option value="medium">T60 0.4–0.9 s</option><option value="long">T60 &gt; 0.9 s</option><option value="unknown">Unmeasured</option></select></label><label>Position<select id="position"><option value="all">Both positions</option><option value="near">Near</option><option value="far">Far</option></select></label>'''+mode_control+'''<label class="check"><input id="clean" type="checkbox" checked>Keep clean references</label><button id="pause">Pause all</button><button id="reset">Reset</button><span class="count" id="count"></span></div><p class="note"><b>Start with a clean reference, then choose a room or decay range.</b> The “Hear ending + tail” button starts just before the original clip ends. Estimated decay (T60) comes from a 20 or 30 dB decay fit of the simulated impulse response. It is an extrapolation, not a recording or a measured real-room decay. There is no added environmental noise on this page.</p>'''+''.join(cards)+'''<section class="provenance"><h2>What these comparisons mean</h2><p>These are simulated impulse responses, with exact configurations, positions, methods and measured decay fits preserved in the source manifest. Names identify simulation conditions, not measured real-world room types. No ASR, transcript correction or quality-gain claim is involved.</p><details><summary>Alignment, levels, tail and source details</summary><p>'''+alignment+''' No original speech samples are cropped. The response is normalized to unit energy, fully convolved, and its RMS over the original clip-duration portion is restored to the original clip RMS. The entire remaining response tail is retained. One final common linear gain per utterance provides headroom across clean and every reverb condition; no clipping, limiter or hidden per-condition headroom gain is used. Preview exports are mono16k PCM16 FLAC.</p><p>T60 estimates from 20 and 30 dB decay fits, when available, extrapolate the −5 to −25 dB and −5 to −35 dB slopes of the impulse energy-decay curve. Configuration targets and measured extrapolations remain separate. Different simulation methods are explicitly labeled and filterable. The page is an auditory preview, not proof of production-policy readiness.</p></details><p>Earlier comparisons remain unchanged: <a href="recorded-noise-reverb-turkish-listening-v2.html">two-position reverb + real noise</a> · <a href="recorded-noise-turkish-listening.html">real cafe, traffic and fan recordings</a>.</p></section><p class="foot">Self-contained: all audio, styling and filters are embedded. Playing one example pauses the others.</p></main><script>
const byId=id=>document.getElementById(id);function filter(){let shown=0;const voice=byId('voice').value;document.querySelectorAll('.utterance').forEach(card=>{let visible=0;card.querySelectorAll('.track').forEach(track=>{const clean=track.dataset.clean==='true';const ok=(voice==='all'||card.dataset.voice===voice)&&(clean?byId('clean').checked:['room','strength','position','mode'].every(key=>byId(key).value==='all'||track.dataset[key]===byId(key).value));track.hidden=!ok;if(ok)visible++;else track.querySelector('audio').pause()});card.hidden=visible===0;shown+=visible});byId('count').textContent=shown+' / '''+str(total)+''' examples'}['voice','room','strength','position','mode','clean'].forEach(id=>byId(id).addEventListener('change',filter));byId('pause').onclick=()=>document.querySelectorAll('audio').forEach(a=>a.pause());byId('reset').onclick=()=>{['voice','room','strength','position','mode'].forEach(id=>byId(id).value='all');byId('clean').checked=true;filter()};document.querySelectorAll('audio').forEach(a=>a.addEventListener('play',()=>document.querySelectorAll('audio').forEach(b=>{if(a!==b)b.pause()})));document.querySelectorAll('.ending').forEach(button=>button.onclick=()=>{const player=button.closest('.player').querySelector('audio');const start=+button.dataset.start;const go=()=>{player.currentTime=start;player.play().catch(()=>{})};if(player.readyState>=1)go();else{player.addEventListener('loadedmetadata',go,{once:true});player.load()}});filter();</script></html>'''
